/* ============ P: PROFILES, PRIVATE LAYER & ACCESS, SAFETY ============ */
function profileView(id,r,o={}){
 const me=id==='me',self=me&&!o.asOther;if(me&&r.p.preview)S.ui.profilePreview=r.p.preview;const p=person(id);const ix=(S.ui.ph||{})[id]||0;const t=r.p.t||'about';
 const displayName=me?(p.name||p.nick||L('Ты','You')):pname(id);const posts=(me?S.myPosts.filter(x=>x.status==='published'):allPosts().filter(x=>x.author===id)).sort((a,b)=>b.t-a.t);
 const mutual=!me&&isMatch(id),liked=!me&&S.likesOut.some(l=>l.p===id),canLike=!self&&(p.dating||p.socialLikes);
 const sh=me?null:shared(id);const inert=h=>o.asOther?h.replace(/ data-(act|go|p|v|id)=("[^"]*"|'[^']*')/g,'').replace(/<button /g,'<button disabled tabindex="-1" '):h;
 const keys=[...fmtList(p.format).slice(0,2).map(x=>opt('format',x)),p.role&&p.role!=='none'&&opt('role',p.role),...(p.dating?(p.seek||[]).slice(0,2).map(s=>opt('seek',s)):[])].filter(Boolean);
 const likeBtn=mutual?`<button class="btn primary" data-act="openChat" data-v="${id}">${I.chat}${L('Написать','Message')}</button>`:liked?`<button class="btn on" data-act="unlikeP" data-v="${id}" aria-pressed="true">${I.heartf}${L('Симпатия','Liked')}</button>`:canLike?`<button class="btn primary" data-act="likeProfile" data-v="${id}">${I.heartf}${L('Нравится','Like')}</button>`:`<button class="btn soft off" title="${L('Не принимает симпатии','Not accepting likes')}">${I.heart}${L('Симпатии выкл.','Likes off')}</button>`;
 const pending=S.reqOut.find(x=>x.p===id&&x.status==='pending');
 const acts=self?`<div class="row g8" style="margin-top:16px"><button class="btn primary" data-go="P02">${I.edit}${L('Редактировать','Edit profile')}</button><button class="btn soft" data-act="shareProfile">${I.share}${L('Поделиться','Share')}</button></div>`
  :inert(`<div class="p-acts">${likeBtn}<button class="btn soft" data-act="follow" data-v="${id}" aria-pressed="${S.follows.has(id)}">${S.follows.has(id)?`${I.check}${L('Подписка','Following')}`:L('Подписаться','Follow')}</button><button class="ibtn" data-act="reqAccess" data-v="${id}" aria-label="${pending?L('Запрос на расширенный профиль отправлен','Private profile request sent'):L('Запросить расширенный профиль','Request private profile')}" title="${L('Расширенный профиль','Private profile')}">${pending?I.clock:I.key}</button></div>`);
 const orgEvents=allEventIds().filter(e=>EV(e).organizer===id&&!isPast(e)&&!EV(e).cancelled&&EV(e).status!=='review');
 const modOf=Object.keys(COMMUNITIES).filter(c=>COMMUNITIES[c].mods.includes(id));
 const kv=[[L('Местоимения','Pronouns'),opt('pron',p.pron)],[L('Гендер','Gender'),(p.gender||[]).map(g=>opt('gender',g)).join(', ')],[L('Ориентация','Orientation'),(p.orient||[]).map(g=>opt('orient',g)).join(', ')],[L('Сейчас','Status'),opt('status',p.status)],[L('Формат отношений','Relationship format'),fmtText(p.format)],[L('Роль','Role'),p.role&&p.role!=='none'?opt('role',p.role):''],[L('Ищет','Looking for'),p.dating?(p.seek||[]).map(s=>opt('seek',s)).join(', '):''],[L('Языки','Languages'),(p.langs||[]).map(x=>({ru:'русский',en:'English',de:'Deutsch'}[x])).join(', ')]].filter(x=>x[1]);
 /* V8: one page — profile, then the private profile right after it when access is open. No tabs. */
 const body=`${T(p.bio)?grp(L('О себе','About'),`<p class="bio">${esc(T(p.bio))}</p>`):self?grp(L('О себе','About'),`<button class="li" data-go="P02"><span class="ico">${I.edit}</span><span class="tx"><b>${L('Добавь пару слов о себе','Add a few words about yourself')}</b><small>${L('Так людям проще начать разговор','It makes starting a conversation easier')}</small></span>${I.chev}</button>`,{list:1}):''}
  ${kv.length?grp(L('Кратко','At a glance'),`<dl class="kv">${kv.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl>`):''}
  ${grp(L('Интересы','Interests'),pubJars(id).length?jarShelf(pubJars(id),{pre:1,act:self?'editJar':'topic',who:id,moreAct:self?'myJarsAll':'allJars'}):`<p class="note">${self?L('Открой интересы в «Я» — они появятся здесь.','Make interests public in Me — they’ll show here.'):L(`${pname(id)} пока не открыл(а) интересы.`,`${pname(id)} hasn’t shared interests yet.`)}</p>`,{foot:pubJars(id).length&&!self?L('Нажми на баночку — увидишь, что это и как у тебя.','Tap a jar to see what it is and how it is for you.'):''})}
  ${posts.length?`<div class="grp"><div class="grp-t"><span>${L('Публикации','Posts')} · ${posts.length}</span></div><div class="posts">${inert(posts.slice(0,3).map((x,i)=>postCard(x,{i})).join(''))}</div></div>`:''}
  ${modOf.length?`<div class="grp"><div class="grp-t"><span>${L('Ведёт сообщества','Runs communities')}</span></div>${modOf.map((c,i)=>commCard(c,{i})).join('')}</div>`:''}
  ${orgEvents.length?`<div class="grp"><div class="grp-t"><span>${L('Организует','Organising')}</span></div>${orgEvents.map(e=>eventCard(e,{row:1,neutral:o.asOther})).join('<div style="height:8px"></div>')}</div>`:''}
  ${self?myPrivSection():me?privSection('me',o):privSection(id)}`;
 const html=`<header class="bar overlay"><button class="ibtn glass" data-back aria-label="${L('Назад','Back')}">${I.back}</button><span style="flex:1"></span>${self?`<button class="ibtn glass" data-go="P02" aria-label="${L('Редактировать','Edit')}">${I.edit}</button>`:inert(`<button class="ibtn glass" data-act="profileMenu" data-v="${id}" aria-label="${L('Ещё','More')}">${I.more}</button>`)}</header>
 <div class="view nodock top0"><div class="wrap">
 ${o.banner||''}
 <div class="hero">${me&&!p.photo?`<div class="plate" style="${PL.rose};position:absolute;inset:0"><span class="pi">${I.me}</span></div>`:photoBg(id,ix)+bigPhoto(id,ix)}${photoBars(id,ix)}${photoCount(id)>1?`<button class="pc-zone l" data-act="pPhoto" data-v="-1" aria-label="${L('Предыдущее фото','Previous photo')}"></button><button class="pc-zone r" data-act="pPhoto" data-v="1" aria-label="${L('Следующее фото','Next photo')}"></button>`:''}${p.photo?`<button class="pc-zone c" data-act="pView" aria-label="${L('Открыть фото на весь экран','Open photo full screen')}"></button>`:''}
  <div class="pc-info"><h2 class="pc-name">${esc(displayName)}${p.age&&p.dating?`<span>${p.age}</span>`:''}${nameBadges(p)}</h2><div class="pc-who"><span>${esc(whoLine(id))}</span><span>${esc(placeLine(id))}</span>${!self&&p.online?`<span class="on">${L('в сети','online')}</span>`:''}</div>${keys.length?`<div class="pc-keys">${keys.map(k=>`<span>${esc(k)}</span>`).join('')}</div>`:''}</div></div>
 ${acts}${followCounts(id)}${pairLine(id,o)}${o.after||''}
 ${!me&&mutual?`<p class="note center mt8">${L('Вы совпали — можно переписываться','You matched — you can chat')}</p>`:''}
 ${!me?`<button class="why mt12" data-go="P05" data-id="${id}">${venn(sh.few?'?':sh.match.length,{mini:1})}<span class="grow"><b>${esc(sharedSummary(id))}</b><span>${L('Что у вас общего','What you share')}</span></span>${I.chev}</button>`:o.asOther?`<div class="why mt12" aria-disabled="true">${venn('?',{mini:1})}<span class="grow"><b>${L('Общие темы — у каждого свои','Shared topics differ per person')}</b><span>${L('Человек увидит своё совпадение с тобой','Each person sees their own overlap with you')}</span></span></div>`:''}
 ${body}</div></div>`;if(me)delete S.ui.profilePreview;return html;
}
SC.P01={title:p=>pname(p.id),valid:p=>!!PEOPLE[p.id]&&!isBlocked(p.id),render:(p,r)=>profileView(p.id,r),after:()=>fillJars()};
SC.P03={title:()=>L('Как видят мой профиль','My profile as others see it'),render:(p,r)=>{const lv=p.lv==='granted'?'granted':'all';S.ui.viewGrant=lv==='granted';try{
 const top=`<div class="alert info mt12">${I.eye}<span><b>${L('Так тебя видят другие','This is how others see you')}</b>${lv==='granted'?L('Так видит человек, которому ты открыл(а) расширенный профиль. Кнопки здесь не работают — это просмотр.','As seen by someone you shared your private profile with. Buttons don’t work here — it’s a preview.'):L('Так видит любой участник без доступа. Кнопки здесь не работают — это просмотр.','As any member without access sees it. Buttons don’t work here — it’s a preview.')}</span></div>${seg([['all',L('Любой участник','Any member')],['granted',L('С доступом','With access')]],lv,'p3lv')}`;
 return profileView('me',r,{asOther:true,grant:lv,banner:'',after:top});}finally{S.ui.viewGrant=false;}},after:()=>fillJars()};
ACT.p3lv=a=>{const r=cur();r.p={...r.p,lv:a.dataset.v};refresh();};

ACT.pPhoto=a=>{const id=cur().id==='P03'?'me':cur().p.id;if(!stepPhoto(id,+a.dataset.v)){const h=$('.hero');h?.classList.remove('nudge-l','nudge-r');void h?.offsetWidth;h?.classList.add(+a.dataset.v<0?'nudge-l':'nudge-r');return;}const h=$('.hero');const ix=S.ui.ph[id];const img=$('.hero>img:not(.mbg),.hero>.plate');if(img){const t=document.createElement('div');t.innerHTML=bigPhoto(id,ix);img.replaceWith(t.firstElementChild);}const bg=$('.hero>.mbg');if(bg){const t=document.createElement('div');t.innerHTML=photoBg(id,ix);if(t.firstElementChild)bg.replaceWith(t.firstElementChild);}$$('.hero .pc-bars i').forEach((b,i)=>b.classList.toggle('on',i===ix));};
ACT.pView=()=>{const id=cur().id==='P03'?'me':cur().p.id;openViewer(photoItems(id),(S.ui.ph||{})[id]||0);};
ACT.toMap=()=>openMe('X01');
ACT.shareProfile=()=>toast(L('Ссылка на профиль скопирована. Без входа она ничего не покажет','Profile link copied. It shows nothing without signing in'),{type:'ok'});
ACT.follow=a=>{const id=a.dataset.v;const on=!S.follows.has(id);on?S.follows.add(id):S.follows.delete(id);
 if(a.classList.contains('btn')&&a.closest('.pc-foot')){a.textContent=on?L('Ты подписан(а)','Following'):L('Подписаться','Follow');}else refresh();
 toast(on?L(`Подписка на ${pname(id)}: посты появятся в «Подписках». Чат это не открывает`,`Following ${pname(id)}: posts appear in Following. This doesn’t open a chat`):L('Ты отписался(ась)','Unfollowed'),{type:on?'ok':''});};
/* R04 — like from a social profile without enrolling in discovery */
ACT.likeProfile=a=>{const id=a.dataset.v;
 if(!S.me.dating&&!S.me.socialLikes){toast(L('Симпатии выключены. Включи их в настройках приватности.','Likes are off. Enable them in privacy settings.'),{type:'warn',action:{label:L('Настройки','Settings'),fn:()=>go('K04')}});return;}const doLike=()=>run(a,()=>{likePerson(id,'profile');refresh();},{ms:300});
 if(S.me.dating||S.ui.r04seen)return doLike();
 sheet(()=>({title:L('Симпатия из профиля','Like from a profile'),lead:`<span class="ico l">${I.heart}</span>`,body:`<div class="fact"><i class="g">${I.check}</i><span>${L(`Если ${pname(id)} ответит взаимностью, откроется личный чат.`,`If ${pname(id)} likes you back, a private chat opens.`)}</span></div><div class="fact"><i class="g">${I.check}</i><span>${L('Твой профиль не появится в подборке знакомств — они у тебя выключены.','Your profile won’t appear in Discover — your dating is off.')}</span></div><div class="fact"><i class="v">${I.info}</i><span>${L('Симпатию можно отменить, человек об этом не узнает.','You can withdraw the like; they won’t be told.')}</span></div>`,foot:`<button class="btn primary" data-act="r04ok" data-v="${id}">${I.heartf}${L('Отправить симпатию','Send like')}</button>`}));};
ACT.r04ok=a=>{S.ui.r04seen=1;closeSheet(true);run(null,()=>{likePerson(a.dataset.v,'profile');refresh();},{ms:300});};
ACT.unlikeP=a=>ACT.unlike(a);

/* profile menu: share / report / block */
ACT.profileMenu=a=>{const id=a.dataset.v;sheet(()=>({title:pname(id),body:`<div class="card list">${linkRow({act:'shareProfile',icon:'link',title:L('Скопировать ссылку','Copy link'),noChev:1})}${S.likesOut.some(l=>l.p===id)?linkRow({act:'unlike',v:id,icon:'heart',title:L('Отменить симпатию','Withdraw like'),noChev:1}):''}${linkRow({act:'report',v:'person',icon:'flag',cls:'danger',title:L('Пожаловаться','Report'),noChev:1})}${linkRow({act:'block',v:id,icon:'block',cls:'danger',title:L('Заблокировать','Block'),sub:L('Прекратит контакт и все доступы','Ends contact and all access'),noChev:1})}</div>`}));};
/* S02 — report */
ACT.report=a=>{const kind=a.dataset.v||'person';S.ui.rp={why:'',block:kind==='person'};closeSheet(true);
 sheet(()=>{const o=S.ui.rp;return{title:L('Пожаловаться','Report'),body:`<p class="lead">${L('Жалобу рассмотрит модератор. Человек не узнает, кто пожаловался.','A moderator reviews the report. The person won’t know who reported.')}</p>${[['threat',L('Угрозы или шантаж','Threats or blackmail')],['private',L('Чужие приватные материалы','Someone else’s private content')],['minor',L('Похоже на несовершеннолетнего','Looks underage')],['spam',L('Спам или мошенничество','Spam or scam')],['other',L('Другое','Something else')]].map(([k,l])=>`<button class="radio ${o.why===k?'on':''}" data-act="rpWhy" data-v="${k}"><i></i><span class="tx">${l}</span></button>`).join('')}
 <label class="field mt16"><span>${L('Подробности','Details')}<i>${L('необязательно','optional')}</i></span><textarea class="inp" id="rpText" rows="3" maxlength="500"></textarea></label>${kind==='person'?`<div class="card list">${toggleRow('rpBlock',L('Также заблокировать','Also block'),L('Сразу прекратить контакт','End contact right away'),o.block)}</div>`:''}`,
 foot:`<button class="btn danger" data-act="rpSend" data-v="${kind}">${L('Отправить жалобу','Send report')}</button>`};});};
ACT.rpWhy=a=>{S.ui.rp.why=a.dataset.v;resheet();};
ACT.rpBlock=()=>{S.ui.rp.block=!S.ui.rp.block;resheet();};
ACT.rpSend=a=>{if(!S.ui.rp.why){toast(L('Выбери причину жалобы','Choose a reason'),{type:'err'});$('#sheet .radio')?.classList.add('shake');return;}
 const id=cur().p.id;run(a,()=>{closeSheet();if(S.ui.rp.block&&id&&PEOPLE[id])doBlock(id);},{ok:L('Жалоба отправлена. Сообщим о решении в уведомлениях','Report sent. We’ll notify you of the decision')});};
ACT.block=a=>{const id=a.dataset.v;closeSheet(true);ask({icon:'block',tone:'l',title:L(`Заблокировать ${pname(id)}?`,`Block ${pname(id)}?`),text:L('Симпатии, чат и выданные доступы прекратятся сразу. Человек не получит уведомление. Разблокировка не вернёт доступы.','Likes, chat and any access you shared end immediately. They won’t be notified. Unblocking doesn’t restore access.'),ok:L('Заблокировать','Block'),danger:true}).then(ok=>{if(ok)run(null,()=>doBlock(id),{ok:L('Заблокировано','Blocked')});});};
function doBlock(id){S.reqOut=S.reqOut.filter(x=>x.p!==id);S.reqIn=S.reqIn.filter(x=>x.p!==id);S.notifs=S.notifs.filter(x=>x.p!==id);S.likesIn=S.likesIn.filter(x=>x.p!==id);S.blocked.unshift({p:id,t:Date.now()});S.matches=S.matches.filter(m=>m.p!==id);S.likesOut=S.likesOut.filter(l=>l.p!==id);S.sharedByMe=S.sharedByMe.filter(x=>x.p!==id);S.follows.delete(id);S.graph[id]?.delete('me');delete S.threads[id];
 const st=stack();while(st.length>1&&st[st.length-1].p&&st[st.length-1].p.id===id)st.pop();render('back');}

/* P05 — shared interests: categories, no universal score */
SC.P05={title:()=>L('Что у вас общего','Shared interests'),valid:p=>!!PEOPLE[p.id]&&!isBlocked(p.id),render:(p)=>{const id=p.id;const s=shared(id);const g=receivedGrant(id);
 return `${bar(L('Что у вас общего','Shared interests'),{back:1,sm:1})}<div class="view nodock"><div class="wrap">
 ${venn(s.few?'?':s.match.length,{pre:1})}<p class="center note" style="margin-top:6px">${L('Ты и','You and')} ${esc(pname(id))}</p>
 <div class="card mt16">
  <div class="cat"><span class="ico g">${I.check}</span><div class="tx"><b>${L('Совпадает','In common')}</b>${s.match.length?`<div class="chips">${s.match.map(m=>`<span class="chip hit">${esc(topic(m))}</span>`).join('')}</div>`:`<p class="note">${L('Пока нет общих открытых тем','No shared public topics yet')}</p>`}</div></div>
  <div class="cat"><span class="ico v">${I.couple}</span><div class="tx"><b>${L('Дополняется','Complements')}</b>${s.complement.length?s.complement.map(c=>`<p class="note" style="color:var(--ink);margin-top:4px">${esc(c)}</p>`).join(''):`<p class="note">${L('Роли не указаны','Roles not specified')}</p>`}</div></div>
  <div class="cat"><span class="ico a">${I.warn}</span><div class="tx"><b>${L('Стоит обсудить','Worth discussing')}</b>${s.discuss.length?s.discuss.map(c=>`<p class="note" style="color:var(--ink);margin-top:4px">${esc(c)}</p>`).join(''):`<p class="note">${L('Явных различий не видно','No obvious differences')}</p>`}</div></div>
  ${s.few?`<div class="cat"><span class="ico">${I.info}</span><div class="tx"><b>${L('Мало данных','Not enough data')}</b><p class="note">${L('Пока мало общего контекста — это не оценка человека.','Not much shared context yet — this isn’t a judgement of the person.')}</p></div></div>`:''}
 </div>
 <div class="alert mt12">${I.lock}<span>${L('Сравниваем только то, что вы оба открыли: публичные интересы, формат и роль.','We compare only what you both made visible: public interests, format and role.')} ${g?L('Расширенный профиль доступен отдельно и не участвует в публичном объяснении.','The private profile is available separately and excluded from the public explanation.'):L('Скрытые темы и границы не участвуют и не раскрываются.','Hidden topics and limits are never used or revealed.')}</span></div>
 ${S.me.jars.filter(j=>j.vis==='public').length<3?`<button class="btn soft mt12" data-act="toMap">${L('Открыть больше своих интересов','Make more of your interests public')}</button>`:''}
 </div></div>`;},after:()=>playVenn()};

/* P06 — request private access: categories, quota, no message, no chat */
ACT.reqAccess=a=>{const id=a.dataset.v||cur().p.id;if(!needAge(()=>ACT.reqAccess({dataset:{v:id}})))return;
 const pend=S.reqOut.find(x=>x.p===id&&x.status==='pending');
 if(pend){sheet(()=>({title:L('Запрос уже отправлен','Request already sent'),lead:`<span class="ico a">${I.clock}</span>`,body:`<p class="lead">${L(`${pname(id)} ещё не ответил(а). Ответ придёт в уведомления.`,`${pname(id)} hasn’t answered yet. You’ll be notified.`)}</p><div class="card list">${linkRow({icon:'lock',title:pend.scopes.map(s=>T(REQ_SCOPES.find(x=>x[0]===s)[1])).join(', '),sub:L('Отправлен','Sent')+' '+F.rel(pend.t),noChev:1})}</div>`,foot:`<button class="btn soft" data-act="cancelReq" data-v="${pend.id}">${L('Отменить запрос','Cancel request')}</button><button class="btn text" data-act="toAccess" data-v="out">${L('Все мои запросы','All my requests')}</button>`}));return;}
 const dec=S.reqOut.find(x=>x.p===id&&x.status==='declined'&&Date.now()-x.t<7*DAY);
 if(dec){toast(L('Повторный запрос этому человеку можно отправить через 7 дней после отказа','You can ask this person again 7 days after a decline'),{type:'warn'});return;}
 if(C.quotaLeft()<=0){limitSheet();return;}
 const scopes=id==='mia'?REQ_SCOPES:REQ_SCOPES.filter(s=>s[0]!=='album');S.ui.rq={id,sel:['info']};
 sheet(()=>{const o=S.ui.rq;const left=C.quotaLeft(),max=S.quota.max;return{title:L('Запросить расширенный профиль','Request private profile'),body:`<p class="lead">${L(`Отметь, что хочешь увидеть. Что открыть — решает ${pname(id)}.`,`Choose what you’d like to see. ${pname(id)} decides what to share.`)}</p>
 ${chipGroup(scopes.map(([k,l])=>[k,T(l)]),o.sel,'rqPick')}
 <div class="sec">${L('Осталось запросов сегодня','Requests left today')}<b style="color:var(--ink)">${left} ${L('из','of')} ${max}</b></div><div class="quota">${Array.from({length:Math.min(max,15)},(_,i)=>`<i class="${i<left?'':'off'}"></i>`).join('')}</div>
 <div class="alert mt16">${I.info}<span>${L('Запрос не отправляет сообщение и не открывает чат. Можно открыть меньше или отказать без объяснения.','A request sends no message and doesn’t open a chat. They can share less or decline without explanation.')}</span></div>`,
 foot:`<button class="btn primary ${o.sel.length?'':'off'}" data-act="rqSend">${L('Отправить запрос','Send request')}</button>`};});};
ACT.rqPick=a=>{const s=S.ui.rq.sel;const i=s.indexOf(a.dataset.v);i<0?s.push(a.dataset.v):s.splice(i,1);resheet();};
ACT.rqSend=a=>{const o=S.ui.rq;if(!o.sel.length){toast(L('Выбери хотя бы один раздел','Pick at least one section'),{type:'err'});return;}
 run(a,()=>{S.reqOut.unshift({id:'o'+Date.now(),p:o.id,scopes:[...o.sel],t:Date.now(),status:'pending'});S.quota.used++;closeSheet();if(['P01','D03','H02','H03'].includes(cur().id))cur().id==='D03'?deckRender():refresh();},{ok:L(`Запрос отправлен. Осталось ${C.quotaLeft()}`,`Request sent. ${C.quotaLeft()} left`)});};
/* B02 — the single paywall moment: quota of new outgoing requests */
function limitSheet(){sheet(()=>({title:L('Запросы на сегодня закончились','No requests left today'),lead:`<span class="ico a">${I.timer}</span>`,body:`<p class="lead">${L(`До ${S.quota.max} новых запросов за 24 часа — это защита от рассылки. Ближайший освободится через 5 ч.`,`Up to ${S.quota.max} new requests per 24 hours — it protects people from spam. The next one frees up in 5 h.`)}</p><p class="note">${L('Отвечать на запросы и отзывать доступ можно всегда.','Answering requests and revoking access are always available.')}</p>`,foot:`<button class="btn primary" data-act="closeSheet">${L('Понятно','Got it')}</button>`}));}
ACT.cancelReq=a=>{const x=S.reqOut.find(y=>y.id===a.dataset.v);run(a,()=>{x.status='cancelled';closeSheet();refresh();},{ok:L('Запрос отменён. Попытка не возвращается','Request cancelled. The attempt isn’t refunded')});};
ACT.toAccess=a=>{closeSheet(true);go('P07',{tab:a.dataset.v||'in'});};

/* P07 — access center: received / sent / shared with me / shared by me */
const SCOPE_TXT=arr=>arr.map(s=>T(REQ_SCOPES.find(x=>x[0]===s)[1])).join(', ');
const REQ_STATUS=()=>({pending:['wait',L('ждёт ответа','pending')],partial:['ok',L('открыт частично','partly shared')],granted:['ok',L('открыт','shared')],declined:['',L('без ответа','no answer')],expired:['',L('истёк','expired')],cancelled:['',L('отменён','cancelled')]});
/** access requests and grants: one body used by P07 and directly by People → Requests (no list page in between) */
function accessBody(p){const t=['in','out','withme','byme'].includes(p.tab)?p.tab:'in';
 const inc=S.reqIn.filter(r=>!isBlocked(r.p)).map(r=>({...r,status:effectiveRequestStatus(r)})),out=S.reqOut.filter(r=>!isBlocked(r.p)).map(r=>({...r,status:effectiveRequestStatus(r)})),withMe=S.reqOut.filter(r=>receivedGrant(r.p)===r),byMe=givenGrantEntries();
 const tabs=tabsRow([['in',L('Ко мне','To me'),C.reqIn()],['out',L('Мои запросы','My requests'),out.filter(r=>r.status==='pending').length],['withme',L('Открыто мне','Shared with me'),withMe.length],['byme',L('Я открыл(а)','I shared'),byMe.length]],t,'p7tab','access-tabs');const sections={};
 let body='';
 {body=`<p class="note" style="margin:0 0 12px">${L('Запросы к тебе бесплатны. Ты решаешь, что открыть и на какой срок. Отказ без объяснений.','Requests to you are free. You decide what to share and for how long. No explanation needed to decline.')}</p>${inc.length?inc.map(r=>`<div class="card" style="margin-bottom:10px"><div class="row">${av(r.p,'')}<button class="grow" style="text-align:left" data-go="P01" data-id="${r.p}"><b style="font-size:16px">${esc(pname(r.p))}${person(r.p).age?', '+person(r.p).age:''}</b><div class="note">${F.rel(r.t)} · ${esc(sharedSummary(r.p))}</div></button></div><div class="chips mt12">${r.scopes.map(s=>`<span class="pill">${esc(T(REQ_SCOPES.find(x=>x[0]===s)[1]))}</span>`).join('')}</div>
  ${r.status==='new'?`<div class="row g8 mt12"><button class="btn md primary" data-act="grant" data-v="${r.id}">${L('Открыть…','Share…')}</button><button class="btn md soft" data-act="decline" data-v="${r.id}">${L('Отказать','Decline')}</button></div>`:`<div class="row mt12" style="gap:8px;font-size:13.5px;font-weight:600;color:${r.status==='open'?'var(--mint)':'var(--mute)'}">${r.status==='open'?I.check:I.x}${r.status==='open'?L(`Открыто: ${SCOPE_TXT(r.granted)} · ${F.left(r.until)}`,`Shared: ${SCOPE_TXT(r.granted)} · ${F.left(r.until)}`):r.status==='expired'?L('Срок доступа истёк','Access has expired'):L('Отказано. Человек видит нейтральное «без ответа»','Declined. They see a neutral “no answer”')}</div>`}</div>`).join(''):empty('lock',L('Запросов нет','No requests'),L('Когда кто-то попросит открыть расширенный профиль, запрос появится здесь.','When someone asks to see your private profile, it appears here.'))}
  <div class="card list mt16">${linkRow({go:'P04',icon:'gear',title:L('Кто может запрашивать','Who can ask'),val:{all:L('все','everyone'),matches:L('совпадения','matches'),none:L('никто','nobody')}[S.me.requestsFrom]})}</div>`;sections.in=body;}
 {const only=p.f==='pending';const list=out.filter(r=>!only||r.status==='pending');body=`<div class="row" style="justify-content:space-between;margin-bottom:10px"><span class="note">${L('Сегодня осталось','Left today')} <b>${C.quotaLeft()} ${L('из','of')} ${S.quota.max}</b></span><button class="chip filter ${only?'on':''}" data-act="p7f">${L('Ждут ответа','Pending')}</button></div>
  ${list.length?`<div class="card list">${list.map(r=>{const [c,l]=REQ_STATUS()[r.status];return `<div class="rqrow"><button class="top" style="width:100%;text-align:left" data-go="P01" data-id="${r.p}">${av(r.p,'')}<span class="grow"><b>${esc(pname(r.p))} <span class="pill ${c}">${l}</span></b><small>${L('Просил(а)','Asked for')}: ${esc(SCOPE_TXT(r.scopes))} · ${F.rel(r.t)}</small>${r.status==='partial'?`<small>${L('Открыто','Shared')}: ${esc(SCOPE_TXT(r.granted))} · ${F.left(r.until)}</small>`:''}</span></button>${r.status==='pending'?`<div class="acts3"><button class="btn text auto" data-act="cancelReq" data-v="${r.id}">${L('Отменить запрос','Cancel request')}</button></div>`:['partial','granted'].includes(r.status)?`<div class="acts3"><button class="btn text auto" data-go="P08" data-id="${r.p}">${L('Смотреть открытое','View shared')}</button></div>`:''}</div>`;}).join('')}</div>`:empty('send',only?L('Ничего не ждёт ответа','Nothing pending'):L('Ты ещё ничего не запрашивал(а)','You haven’t asked for anything yet'),L('Запросить доступ можно в профиле человека или в подборке.','You can request access on a profile or in Discover.'))}
  <p class="note mt12">${L('Отказ показывается как «без ответа». Повторный запрос тому же человеку — не раньше чем через 7 дней.','A decline shows as “no answer”. You can ask the same person again after 7 days.')}</p>`;sections.out=body;}
 {body=withMe.length?`<div class="card list">${withMe.map(r=>linkRow({go:'P08',p:{id:r.p},av:av(r.p,''),title:pname(r.p),sub:`${SCOPE_TXT(r.granted)} · ${F.left(r.until)}`})).join('')}</div>`:empty('unlock',L('Пока никто не открыл','Nothing shared with you yet'),L('Здесь появятся расширенные профили, которые тебе открыли.','Private profiles shared with you appear here.'));;sections.withme=body;}
 {body=byMe.length?byMe.map(x=>`<div class="card" style="margin-bottom:10px"><div class="row">${whoLink(x.p,'')}<div class="grow"><button class="plink pnm" ${profGo(x.p)}>${esc(pname(x.p))}</button><div class="note">${esc(SCOPE_TXT(x.scopes))}</div></div><span class="pill">${x.until?F.left(x.until):L('без срока','no limit')}</span></div><div class="row g8 mt12"><button class="btn md soft" data-act="narrow" data-v="${x.p}">${L('Изменить','Change')}</button><button class="btn md danger" data-act="revoke" data-v="${x.p}">${L('Отозвать','Revoke')}</button></div></div>`).join(''):empty('lock',L('Ты никому не открывал(а) доступ','You haven’t shared with anyone'),L('Открыть можно, ответив на запрос.','You can share by answering a request.'));;sections.byme=body;}
 return `${tabs}${sections[t]}`;}
SC.P07={title:()=>L('Доступы','Access'),render:(p)=>`${bar(L('Доступы','Access'),{back:1,sm:1})}<div class="view nodock"><div class="wrap">${accessBody(p)}</div></div>`,after:()=>{$('#main .tabs .on')?.scrollIntoView({block:'nearest',inline:'nearest'});}};

ACT.p7tab=a=>{const r=cur();r.p.tab=a.dataset.v;r.scroll=0;render('fade');};
ACT.p7f=()=>setP('f',cur().p.f==='pending'?'':'pending');
/* P09 — review an incoming request: choose less, set a term, preview; no chat toggle */
ACT.grant=a=>{const r=S.reqIn.find(x=>x.id===a.dataset.v);S.ui.gr={id:r.id,sel:[...r.scopes],term:'7'};
 sheet(()=>{const o=S.ui.gr;return{title:L(`Что открыть ${pname(r.p)}`,`What to share with ${pname(r.p)}`),body:`<p class="lead">${L('Просит','Asks for')}: ${esc(SCOPE_TXT(r.scopes))}. ${L('Можно открыть меньше.','You can share less.')}</p>
 ${chipGroup(r.scopes.map(s=>[s,T(REQ_SCOPES.find(x=>x[0]===s)[1])]),o.sel,'grPick')}
 <div class="sec">${L('Срок','Duration')}</div>${seg([['1',L('24 часа','24 hours')],['7',L('7 дней','7 days')],['0',L('Без срока','No limit')]],o.term,'grTerm','sm')}
 <div class="sec">${L(`Что увидит ${pname(r.p)}`,`What ${pname(r.p)} will see`)}</div><div class="card list">${o.sel.length?o.sel.map(s=>`<div class="li"><span class="ico g">${I.unlock}</span><span class="tx"><b>${esc(T(REQ_SCOPES.find(x=>x[0]===s)[1]))}</b><small>${s==='info'?L('Темы с видимостью «по разрешению», включая границы','Topics marked “by permission”, including limits'):s==='photos'?L('3 фото с персональным водяным знаком','3 photos with a personal watermark'):L('Только текущее содержимое; новое — отдельным решением','Current content only; new items need a new decision')}</small></span></div>`).join(''):`<p class="note" style="padding:12px 0">${L('Ничего не выбрано','Nothing selected')}</p>`}</div>
 <p class="note mt12">${L('Доступ не открывает чат. Отозвать можно в любой момент — у человека всё пропадёт сразу.','Access doesn’t open a chat. Revoke any time — it disappears for them at once.')}</p>`,
 foot:`<button class="btn primary ${o.sel.length?'':'off'}" data-act="grOk">${I.unlock}${L('Открыть доступ','Share access')}</button>`};});};
ACT.grPick=a=>{const s=S.ui.gr.sel;const i=s.indexOf(a.dataset.v);i<0?s.push(a.dataset.v):s.splice(i,1);resheet();};
ACT.grTerm=a=>{S.ui.gr.term=a.dataset.v;resheet();};
ACT.grOk=a=>{const o=S.ui.gr;const r=S.reqIn.find(x=>x.id===o.id);const until=o.term==='0'?null:Date.now()+(+o.term)*DAY;
 run(a,()=>{r.status='open';r.granted=[...o.sel];r.until=until;S.sharedByMe.unshift({p:r.p,scopes:[...o.sel],until,t:Date.now()});closeSheet();refresh();},{ok:L(`Открыто ${pname(r.p)}`,`Shared with ${pname(r.p)}`)});};
ACT.decline=a=>{const r=S.reqIn.find(x=>x.id===a.dataset.v);run(a,()=>{r.status='no';refresh();},{ok:L('Отказано. Человек увидит «без ответа»','Declined. They’ll see “no answer”'),undo:()=>{r.status='new';refresh();}});};
/* P11 — revoke */
ACT.revoke=a=>{const id=a.dataset.v;ask({icon:'lock',tone:'l',title:L(`Отозвать доступ у ${pname(id)}?`,`Revoke access for ${pname(id)}?`),text:L('Новые просмотры прекратятся сразу. То, что человек уже видел или сохранил вне FetUre, отозвать нельзя. Чат и симпатия не меняются.','New views stop immediately. What they already saw or saved outside FetUre can’t be recalled. Chat and likes stay as they are.'),ok:L('Отозвать','Revoke'),danger:true}).then(ok=>{if(!ok)return;run(null,()=>{S.sharedByMe=S.sharedByMe.filter(x=>x.p!==id);const r=S.reqIn.find(x=>x.p===id&&x.status==='open');if(r)r.status='no';refresh();},{ok:L('Доступ отозван','Access revoked')});});};
ACT.narrow=a=>{const x=givenGrant(a.dataset.v);if(!x){toast(L('Доступ уже завершён','Access has ended'),{type:'warn'});refresh();return;}S.ui.nw={p:x.p,sel:[...x.scopes]};sheet(()=>({title:L('Изменить доступ','Change access'),body:`<p class="lead">${L('Убери то, что больше не хочешь показывать.','Remove what you no longer want to share.')}</p>${chipGroup(x.scopes.map(s=>[s,T(REQ_SCOPES.find(y=>y[0]===s)[1])]),S.ui.nw.sel,'nwPick')}`,foot:`<button class="btn primary" data-act="nwOk">${L('Сохранить','Save')}</button>`}));};
ACT.nwPick=a=>{const s=S.ui.nw.sel;const i=s.indexOf(a.dataset.v);i<0?s.push(a.dataset.v):s.splice(i,1);resheet();};
ACT.nwOk=a=>{const o=S.ui.nw,x=givenGrant(o.p);if(!x){closeSheet(true);toast(L('Доступ уже завершён','Access has ended'),{type:'warn'});refresh();return;}if(!o.sel.length){closeSheet(true);ACT.revoke({dataset:{v:o.p}});return;}run(a,()=>{x.scopes=x.scopes.filter(k=>o.sel.includes(k));S.reqIn.filter(y=>y.p===o.p&&y.status==='open'&&grantTimeActive(y.until)).forEach(y=>y.granted=[...x.scopes]);closeSheet();refresh();},{ok:L('Доступ изменён','Access updated')});};

/* P08 — private profile shared with me */
/* P08 — V8: the private profile is a continuation of the profile, not a separate screen */
const activeGrant=receivedGrant;
/** What a person with access sees in someone's private layer. One projection for seed people and for me,
 *  so «Как видят» (my preview) and a real granted view render through the same code. */
const SEED_PRIV_JARS=[{t:'shibari',lv:9},{t:'sensory',lv:8},{t:'temperature',lv:6},{t:'roleplay',lv:7},{t:'aftercare',lv:10},{t:'filming',lv:0,limit:'hard'},{t:'strongpain',lv:0,limit:'discuss'},{t:'publicplace',lv:0,limit:'hard'}];
function privProj(id){
 if(id==='me')return{jars:S.me.jars.filter(j=>j.vis==='granted'),text:T(S.me.privText)||'',media:privMedia().map(m=>({type:m.type,src:privSrc(m),style:m.style,sec:m.type==='video'?'video':m.sec,dur:m.dur}))};
 const P0=person(id);return{jars:SEED_PRIV_JARS,text:T(P0?.privText)||'',media:P0?.photo?[0,1,2,3,4,5].map(k=>({type:'image',src:IMG(P0.photo),style:CROPS[k%6],sec:k<3?'photos':'album'})):[]};}
/** sections a grant opens: info → text + wishes & limits; photos/album/video → those media sections */
function privOpenHTML(id,g,o={}){const pr=privProj(id),has=k=>g.granted.includes(k);
 const media=pr.media.filter(m=>has(m.sec));const wishes=pr.jars.filter(j=>!j.limit),limits=pr.jars.filter(j=>j.limit);
 const info=has('info')?`${pr.text?grp(L('От себя','In their words'),`<p class="bio">${esc(pr.text)}</p>`):''}${wishes.length?grp(L('Желания','Wishes'),jarsHTML(wishes,{act:o.preview?'':'topic',who:id})):''}${limits.length?grp(L('Границы','Limits'),jarsHTML(limits,{act:o.preview?'':'topic',who:id})):''}${!pr.text&&!pr.jars.length?`<p class="note">${L('Здесь пока ничего нет.','Nothing here yet.')}</p>`:''}`:'';
 const wm=o.preview?L('ник зрителя','viewer’s nick'):(S.me.nick||'');
 const mediaHTML=media.length?grp(L(`Фото и видео · ${media.length}`,`Photos & video · ${media.length}`),`<div class="pgrid">${media.map((m,k)=>`<button class="pcell" ${o.preview?'disabled':`data-act="privPeek" data-v="${id}" data-i="${k}"`}>${m.type==='video'?`<video src="${esc(m.src)}" muted playsinline preload="metadata"></video>`:`<img src="${esc(m.src)}" alt="" style="${m.style||''}" draggable="false">`}<span class="wm">${esc(wm)}</span></button>`).join('')}</div>`,{foot:o.preview?L('Каждый видит с собственным водяным знаком.','Everyone sees them with their own watermark.'):L('С твоим водяным знаком. Доступ могут отозвать в любой момент — уважай доверие.','With your watermark. Access can be revoked any time — respect the trust.')}):'';
 const head=`<div class="grp-t" id="priv"><span>${I.unlock} ${L('Расширенный профиль','Private profile')}</span><span class="note">${g.until?esc(F.left(g.until)):''}</span></div>`;
 return `<section class="priv-open">${head}<div class="priv-in">${info}${mediaHTML}</div></section>`;}
function privSection(id,o={}){
 if(id==='me'){const g=o.grant==='granted'?{granted:['info','photos','album','video'],until:null}:null;
  if(!g)return grp(L('Расширенный профиль','Private profile'),veilBlock('me').replace(/ data-(act|v)="[^"]*"/g,'').replace(/<button /g,'<button disabled tabindex="-1" '),{inner:'flat veil-card'});
  return privOpenHTML('me',g,{preview:1});}
 const g=activeGrant(id);if(!g)return grp(L('Расширенный профиль','Private profile'),veilBlock(id),{inner:'flat veil-card'});
 return privOpenHTML(id,g);}
function myPrivSection(){const jars=S.me.jars.filter(j=>j.vis==='granted');const media=privMedia();
 const head=`<div class="grp-t" id="priv"><span>${I.key} ${L('Расширенный профиль','Private profile')}</span><button data-go="P04">${L('Изменить','Edit')}</button></div>`;
 const empty=!jars.length&&!media.length;
 return `<section class="priv-open">${head}<p class="grp-n" style="margin:0 4px 10px">${L('Это продолжение профиля видят только те, кому ты откроешь доступ.','Only people you give access to see this part of your profile.')}</p><div class="priv-in">
 ${empty?grp('',`<button class="li" data-go="P04"><span class="ico a">${I.plus}</span><span class="tx"><b>${L('Пока пусто','Nothing here yet')}</b><small>${L('Добавь желания, границы, фото или видео','Add wishes, limits, photos or video')}</small></span>${I.chev}</button>`,{list:1}):''}
 ${jars.length?grp(L('Желания и границы','Wishes & limits'),jarsHTML(jars,{act:'editJar',who:'me'})):''}
 ${media.length?`<section class="grp"><div class="grp-t"><span>${L('Фото и видео','Photos & video')} · ${media.length}</span></div><div class="pgrid">${media.slice(0,6).map((m,i)=>`<button class="pcell" data-act="privView" data-v="${i}">${m.type==='video'?`<video src="${esc(privSrc(m))}" muted playsinline preload="metadata"></video>`:`<img src="${esc(privSrc(m))}" alt="" style="${m.style||''}" draggable="false">`}<span class="wm">${esc(S.me.nick||'')}</span></button>`).join('')}</div><p class="grp-n">${L('Другие увидят их со своим водяным знаком.','Others see them with their own watermark.')}</p></section>`:''}
 </div></section>`;}
ACT.privPeek=a=>{const id=a.dataset.v,g=activeGrant(id);const media=g?privProj(id).media.filter(m=>g.granted.includes(m.sec)):[];if(!person(id)||!media.length){toast(L('Доступ к фото недоступен','Photo access is unavailable'),{type:'warn'});refresh();return;}openViewer(media.map(m=>({type:m.type,src:m.src,style:m.style,wm:'@'+(S.me.nick||'')})),+a.dataset.i);};
SC.P08={title:p=>pname(p.id),valid:p=>!!PEOPLE[p.id]&&!isBlocked(p.id),render:(p,r)=>profileView(p.id,r),after:()=>{fillJars();setTimeout(()=>$('#priv')?.scrollIntoView({block:'start',behavior:'smooth'}),120);}};

/* P02 — edit my profile: one source of truth for every screen */
SC.P02={title:()=>L('Редактировать профиль','Edit profile'),render:(p,r)=>{const m=S.me;
 if(!r.init){r.init=1;Object.assign(r.f,{name:m.name,nick:m.nick,bio:T(m.bio),city:m.city||''});r.photos=[...m.photos];r.pron=m.pron;r.gender=[...m.gender];r.orient=[...m.orient];r.format=[...fmtList(m.format)];r.status=m.status||null;r.role=m.role;r.langs=[...m.langs];r.vis={...PUBLIC_VIS,...m.vis};}
 const visBtn=k=>`<button class="pill ${r.vis[k]==='public'?'ok':r.vis[k]==='granted'?'v':''}" data-act="visCycle" data-v="${k}">${r.vis[k]==='public'?I.globe:r.vis[k]==='granted'?I.lock:I.eyeoff}${{public:L('всем','everyone'),granted:L('по доступу','by access'),only:L('только я','only me')}[r.vis[k]]}</button>`;
 return `${bar(L('Профиль','Profile'),{back:1,sm:1,actions:`<button class="btn text auto" data-act="previewDraft">${L('Как видят','Preview')}</button>`})}<div class="view nodock cta1"><div class="wrap">
 <section class="grp"><div class="grp-t"><span>${L('Фото','Photos')}</span><span class="note">${r.photos.length}/6 · ${L('формат 4:5','4:5 format')}</span></div><div class="card"><div class="edit-ph">${r.photos.map((ph,i)=>`<div><img src="${IMG(ph)}" alt="">${i===0?`<span class="mainph">${L('главное','main')}</span>`:''}<button class="vw" data-act="phMenu" data-v="${i}" aria-label="${L('Действия с фото','Photo actions')} ${i+1}"></button><button class="rm" data-act="phRm" data-v="${i}" aria-label="${L('Удалить фото','Remove photo')}">${I.close}</button></div>`).join('')}${r.photos.length<6?`<button data-act="phAdd" aria-label="${L('Добавить фото','Add photos')}">${I.camera}<small>${L('Добавить','Add')}</small></button>`:''}</div>
 <p class="note mt8">${L('Можно выбрать сразу несколько. Сжимаем и стираем геометку прямо на телефоне. Нажми на фото, чтобы кадрировать или сделать главным.','Pick several at once. We compress and wipe location on your phone. Tap a photo to crop it or make it main.')}</p>
 </div></section><section class="grp"><div class="grp-t"><span>${L('Основное','Basics')}</span></div><div class="card form-card">${field({name:'name',label:L('Имя','Name'),ph:'Alex',max:30})}
 ${field({name:'nick',label:L('Ник','Nickname'),icon:'at',attrs:'autocapitalize="off" spellcheck="false"',hint:L('Ник — часть аккаунта, отдельного «ника для знакомств» нет.','Your nickname belongs to your account — there’s no separate dating nickname.')})}
 ${field({name:'bio',label:L('О себе','About you'),textarea:1,max:500,ph:L('Пара фраз о том, что для тебя важно','A few lines about what matters to you'),attrs:'rows="4"'})}
 <button class="li" data-act="peCity"><span class="ico">${I.pin}</span><span class="tx"><b>${L('Город','City')}</b><small>${r.f.city?esc(placeCaption(r.f.city)):L('Не показывать','Don’t show')}</small></span>${I.chev}</button><button class="btn text auto" data-act="peHideCity">${L('Не показывать город','Hide city')}</button>
 </div></section><section class="grp"><div class="grp-t"><span>${L('Кто ты','About you')}</span><span class="note">${L('видимость — у каждого поля','visibility per field')}</span></div><div class="card form-card"><div class="field"><span class="flabel">${L('Местоимения','Pronouns')}</span>${chipGroup(optItems('pron'),[r.pron],'peOne',{k:'pron'})}</div>
 ${[['gender',L('Гендер','Gender'),1],['orient',L('Ориентация','Orientation'),1],['status',L('Сейчас','Current status'),0],['format',L('Формат отношений','Relationship format'),1],['role',L('Роль','Role'),0]].map(([k,l,multi])=>`<div class="field"><span class="flabel">${l}${visBtn(k)}</span>${IDENTITY_KEYS.includes(k)?identityChoices(k,r[k],multi?'peMulti':'peOne'):chipGroup(optItems(k),[r[k]],'peOne',{k,title:l})}</div>`).join('')}
 <div class="field"><span class="flabel">${L('Языки','Languages')}</span>${chipGroup([['ru','русский'],['en','English'],['de','Deutsch']],r.langs,'peMulti',{k:'langs'})}</div>
 </div></section><section class="grp"><div class="grp-t"><span>${L('Ещё','More')}</span></div><div class="card list">${linkRow({go:'P04',icon:'key',tone:'a',title:L('Расширенный профиль','Private profile'),sub:L('Фото, видео и желания — по запросу и на срок','Photos, video and wishes — on request, for a set time')})}${linkRow({go:'X02',icon:'spark',tone:'l',title:L('Интересы и границы','Interests & limits'),sub:L('Мои баночки: значение темы и кто её видит — все, по доступу или только ты','My jars: each topic’s value and who sees it — everyone, by access or only you')})}</div></section>
 </div></div><div class="ctabar"><div class="wrap"><button class="btn primary" data-act="peSave">${L('Сохранить','Save')}</button></div></div>`;}};
ACT.visCycle=a=>{const r=cur();const k=a.dataset.v;const order=['public','granted','only'];r.vis[k]=order[(order.indexOf(r.vis[k])+1)%3];r.dirty=true;refresh();toast({public:L('Видно всем участникам','Visible to all members'),granted:L('Только тем, кому ты открыл(а) доступ','Only people you’ve shared access with'),only:L('Видишь только ты','Only you can see it')}[r.vis[k]]);};
ACT.peOne=a=>{const r=cur(),k=a.dataset.k;r[k]=k==='role'?toggleIdentityValue(r[k],k,a.dataset.v):r[k]===a.dataset.v?null:a.dataset.v;r.dirty=true;refresh();};
ACT.peMulti=a=>{const r=cur(),k=a.dataset.k;r[k]=toggleIdentityValue(r[k],k,a.dataset.v);r.dirty=true;refresh();};
ACT.phAdd=()=>{const r=cur();openUploader({max:6,have:r.photos.length,accept:'image',aspect:'4:5',title:L('Фото профиля','Profile photos'),done:items=>{r.photos.push(...items.map(i=>i.url));r.dirty=true;refresh();}});};
ACT.phMenu=a=>{const i=+a.dataset.v;const r=cur();sheet(()=>({title:L(`Фото ${i+1}`,`Photo ${i+1}`),body:`<div class="card list">${linkRow({act:'phView',v:i,icon:'eye',title:L('Посмотреть','View'),noChev:1})}${linkRow({act:'phCrop',v:i,icon:'edit',title:L('Кадрировать','Crop'),noChev:1})}${i?linkRow({act:'phMain',v:i,icon:'check',title:L('Сделать главным','Make main'),sub:L('Его увидят первым в профиле и подборке','Shown first on your profile and in Discover'),noChev:1}):''}${linkRow({act:'phRm',v:i,icon:'trash',cls:'danger',title:L('Удалить','Delete'),noChev:1})}</div>`}));};
ACT.phView=a=>{closeSheet(true);openViewer(cur().photos.map(ph=>({type:'image',src:IMG(ph)})),+a.dataset.v);};
ACT.phMain=a=>{closeSheet(true);const r=cur();const [ph]=r.photos.splice(+a.dataset.v,1);r.photos.unshift(ph);r.dirty=true;refresh();toast(L('Теперь это главное фото','This is now your main photo'),{type:'ok'});};
ACT.phCrop=a=>{closeSheet(true);const r=cur(),i=+a.dataset.v;const src=IMG(r.photos[i]);S.ui.up=null;openCrop(src,'4:5',{x:0,y:0,z:1},async crop=>{const c=await cropImage({full:src,crop},'4:5');r.photos[i]=c.url;r.dirty=true;refresh();toast(L('Кадр сохранён','Crop saved'),{type:'ok'});});};
ACT.phRm=a=>{if(S.ui.sheet)closeSheet(true);const r=cur();if(requiresDiscoveryPhoto(S.me)&&r.photos.length===1){toast(L('Для показа в подборке нужно фото. Сначала выключи показ анкеты в настройках.','A photo is required to appear in Discover. Turn off profile visibility in settings first.'),{type:'warn'});return;}r.photos.splice(+a.dataset.v,1);r.dirty=true;refresh();};
ACT.peSave=a=>{const r=cur();if(requiresDiscoveryPhoto(S.me)&&!r.photos.length){toast(L('Для показа в подборке нужно хотя бы одно фото','At least one photo is required to appear in Discover'),{type:'warn'});return;}r.err={};const nk=fv('nick').trim();const ne=nk.toLowerCase()===S.me.nick.toLowerCase()?'':V.nick(nk);if(ne)r.err.nick=ne;if(fv('bio').length>500)r.err.bio=L('Максимум 500 символов','500 characters max');if(fv('name').length>30)r.err.name=L('Максимум 30 символов','30 characters max');
 if(Object.keys(r.err).length){refresh();shakeFirstErr();toast(L('Проверь отмеченные поля','Check the highlighted fields'),{type:'err'});return;}
 run(a,()=>{Object.assign(S.me,{name:fv('name').trim(),nick:nk,bio:{ru:fv('bio'),en:fv('bio')},city:r.f.city||null,photos:[...r.photos],photo:r.photos[0]||null,pron:r.pron,gender:r.gender,orient:r.orient,format:[...r.format],status:r.status,role:r.role,langs:[...r.langs],vis:{...r.vis}});r.dirty=false;back();},{ok:L('Профиль обновлён — изменения видны везде','Profile updated — changes show everywhere')});};

/* P04 — V7 «Приватное»: what you share by request — wishes & limits, private photos/video, albums */
const PRIV_SEC=()=>[['photos',L('Фото','Photos')],['video',L('Видео','Video')],['album',L('Альбом «Лето»','Album “Summer”')]];
function privMedia(){if(!S.me.media){S.me.media=S.persona!=='new'?[...[0,1,2].map(i=>({id:'pm'+i,type:'image',src:8,style:CROPS[i+1],sec:'photos'})),...[3,4,5,0,1,2].map((v,i)=>({id:'pa'+i,type:'image',src:8,style:CROPS[v],sec:'album'}))]:[];}return S.me.media;}
const privSrc=m=>m.url||IMG(m.src);
MEDIA_SRC.priv=()=>privMedia().filter(m=>!S.ui.privSec||m.sec===S.ui.privSec).map(m=>({type:m.type,url:privSrc(m),style:m.style,dur:m.dur}));
SC.P04={title:()=>L('Расширенный профиль','Private profile'),render:(p,r)=>{const sec=p.sec||'';S.ui.privSec=sec;const all=privMedia();const list=all.filter(m=>!sec||m.sec===sec);const gj=S.me.jars.filter(j=>j.vis==='granted');if(r.f.privText===undefined)r.f.privText=T(S.me.privText)||'';
 if(p.add&&!r.opened){r.opened=1;setTimeout(()=>{if(cur()===r)ACT.privAdd();},300);}
 return `${bar(L('Расширенный профиль','Private profile'),{back:1,sm:1,actions:`<button class="ibtn" data-act="privAdd" aria-label="${L('Добавить фото или видео','Add photos or video')}">${I.plus}</button>`})}<div class="view nodock"><div class="wrap">
 <p class="lead" style="margin:4px 4px 0">${L('Видят только те, кому ты сам(а) откроешь доступ — выбранные разделы и на выбранный срок.','Only people you choose see this — the sections you pick, for the time you set.')}</p>
 <section class="grp"><div class="grp-t"><span>${L('Текст от себя','In your own words')}</span></div><div class="card form-card">${field({name:'privText',label:L('Что важно знать тем, кому ты откроешь доступ','What people you share with should know'),textarea:1,max:1000,ph:L('Например: как я люблю договариваться, что для меня важно до встречи','E.g. how I like to agree on things, what matters to me before meeting'),attrs:'rows="4"'})}<button class="btn soft sm" data-act="privTextSave">${L('Сохранить текст','Save text')}</button></div></section>
 <section class="grp"><div class="grp-t"><span>${L('Желания и границы','Wishes & limits')} · ${gj.length}</span><button data-go="X02">${L('Изменить','Edit')}</button></div>
 <p class="grp-n" style="margin:0 2px 10px">${L('Это твои баночки с видимостью «по доступу». Видимость каждой темы меняется в «Мои баночки»: нажми на баночку → «Кто видит». Человек с доступом увидит ровно это:','These are your jars set to “by access”. Change each topic’s visibility in My jars: tap a jar → “Who can see”. Someone with access sees exactly this:')}</p>
 <div class="card">${gj.length?jarsHTML(gj,{act:'editJar',who:'me'}):`<p class="note">${L('Пока ни одной темы «по доступу». Человек с доступом не увидит желаний и границ.','No “by access” topics yet. Someone with access won’t see any wishes or limits.')}</p>`}</div>
 <p class="grp-n">${L('Темы «всем» видны в обычном профиле, «только я» — никому.','“Everyone” topics show on your regular profile, “only me” — to no one.')} <button class="btn text auto" style="min-height:0;padding:0" data-go="P03" data-p='{"lv":"granted"}'>${L('Посмотреть, как видят с доступом','See it as someone with access')}</button></p></section>
 <section class="grp"><div class="grp-t"><span>${L('Фото и видео','Photos & video')} · ${all.length}</span></div>
 ${all.length?`<div class="chips scroll" style="margin-bottom:10px">${[['',L('Все','All')],...PRIV_SEC()].map(([k,l])=>`<button class="chip filter ${sec===k?'on':''}" data-act="privSec" data-v="${k}">${l} <span style="opacity:.6">${k?all.filter(m=>m.sec===k).length:all.length}</span></button>`).join('')}</div>
 <div class="pgrid">${list.map((m,i)=>`<button class="pcell" data-act="privView" data-v="${i}" aria-label="${L('Открыть','Open')}">${m.type==='video'?`<video src="${esc(privSrc(m))}" muted playsinline preload="metadata"></video><span class="dur">${I.video}${fmtDur(m.dur||0)}</span>`:`<img src="${esc(privSrc(m))}" alt="" style="${m.style||''}" draggable="false">`}<span class="wm">${esc(S.me.nick||'')}</span></button>`).join('')}<button class="pcell add" data-act="privAdd">${I.plus}<small>${L('Добавить','Add')}</small></button></div>`
 :`<div class="card list"><button class="li" data-act="privAdd"><span class="ico v">${I.image}</span><span class="tx"><b>${L('Добавь приватные фото или видео','Add private photos or video')}</b><small>${L('До 6 за раз. Геометку стираем на телефоне.','Up to 6 at a time. Location is wiped on your phone.')}</small></span>${I.chev}</button></div>`}
 <p class="grp-n">${L('Кому откроешь, увидит их со своим водяным знаком.','People you share with see them with their own watermark.')}</p></section>
 ${grp(L('Кто может просить доступ','Who can ask for access'),choices([['all',L('Все участники','All members')],['matches',L('Только взаимные симпатии','Mutual likes only')],['none',L('Никто','Nobody'),L('Уже выданные доступы останутся','Access already shared stays')]],S.me.requestsFrom,'reqFrom'))}
 ${grp('',linkRow({go:'P07',p:{tab:'byme'},icon:'unlock',title:L('Кому уже открыто','Already shared with'),val:String(givenGrantEntries().length)}),{list:1})}
 </div></div>`;}};
ACT.privSec=a=>{cur().p.sec=a.dataset.v;refresh();};
ACT.privTextSave=a=>{const r=cur();const v=fv('privText').trim().slice(0,1000);run(a,()=>{S.me.privText=v;r.f.privText=v;r.dirty=false;refresh();},{ms:300,ok:L('Текст сохранён — его видят только те, кому ты откроешь доступ','Saved — only people you share access with can see it')});};
ACT.privView=a=>{MEDIA_SRC.priv&&openViewer(MEDIA_SRC.priv().map(m=>({type:m.type,src:m.url,style:m.style,wm:'@'+(S.me.nick||'')})),+a.dataset.v);};
ACT.privAdd=()=>{const sec=cur().p.sec||'photos';openUploader({max:6,have:0,accept:'media',aspect:null,aspects:['orig','4:5','1:1'],title:L('Приватные фото и видео','Private photos & video'),done:items=>{privMedia().unshift(...items.map(i=>({id:'pm'+Math.random().toString(36).slice(2,7),type:i.type,url:i.url,dur:i.dur,sec:i.type==='video'?'video':sec==='album'?'album':'photos'})));refresh();}});};
ACT.p4sec=a=>{if(a.dataset.v==='info')return openMe('X01');go('P04',{sec:a.dataset.v});};
ACT.reqFrom=a=>run(null,()=>{S.me.requestsFrom=a.dataset.v;refresh();},{ms:300,ok:L('Сохранено','Saved')});

/* Q01 — partner link */
ACT.pairLink=()=>{sheet(()=>({title:L('Профиль пары','Couple profile'),lead:`<span class="ico v">${I.couple}</span>`,body:`<p class="lead">${L('Пара — это общий профиль двух отдельных аккаунтов. Личные интересы и чаты остаются у каждого свои.','A couple is a shared profile of two separate accounts. Personal interests and chats stay separate.')}</p>
 <div class="fact"><i class="g">${I.check}</i><span>${L('Общими станут: описание пары, правила и совместные публикации','Shared: couple description, rules and joint posts')}</span></div><div class="fact"><i class="g">${I.check}</i><span>${L('Совместные фото и доступы — только с согласия обоих','Joint photos and access — only with both agreeing')}</span></div>
 <label class="field mt16"><span>${L('Ник партнёра','Partner’s nickname')}</span><div class="inwrap">${I.at}<input class="inp" id="pairNick" placeholder="kira" autocapitalize="off"></div></label>`,foot:`<button class="btn primary" data-act="pairSend">${L('Отправить приглашение','Send invitation')}</button>`}));};
ACT.pairSend=a=>{const v=$('#pairNick').value.trim().toLowerCase();if(!v){$('#pairNick').classList.add('err');toast(L('Укажи ник партнёра','Enter your partner’s nickname'),{type:'err'});return;}if(!PEOPLE[v]){$('#pairNick').classList.add('err');toast(L('Такого ника нет. Проверь написание','No such nickname. Check the spelling'),{type:'err'});return;}run(a,()=>{S.pairInvite={p:v,t:Date.now()};closeSheet();refresh();},{ok:L(`Приглашение отправлено ${pname(v)}. Пара появится после её/его согласия`,`Invitation sent to ${pname(v)}. The couple appears once they accept`)});};

ACT.previewDraft=()=>{const r=cur();const value={...S.me,name:fv('name'),nick:fv('nick'),bio:{ru:fv('bio'),en:fv('bio')},city:r.f.city||null,photos:[...r.photos],photo:r.photos[0]||null,pron:r.pron,gender:[...r.gender],orient:[...r.orient],format:[...r.format],status:r.status,role:r.role,langs:[...r.langs],vis:{...r.vis}};go('P03',{preview:value},{keepDraft:true});};
ACT.peCity=()=>openCityPicker(cur().f.city,id=>{cur().f.city=id;cur().dirty=true;refresh();});
ACT.peHideCity=()=>{cur().f.city='';cur().dirty=true;refresh();};


/* ---------- V10 revision part 2: badges, followers / following ---------- */
/** small badges after a name: photo verification and Premium. Neither opens private data or chat. */
function nameBadges(p,sm){if(!p)return '';return `${p.pv?`<span class="nbadge v" title="${L('Фото подтверждено','Photo verified')}" role="img" aria-label="${L('Фото подтверждено','Photo verified')}">${I.verified}</span>`:''}${p.premium?`<span class="nbadge p" title="Premium" role="img" aria-label="Premium">${I.crown}</span>`:''}`;}
/** follow graph: counts are always the length of the lists people can open */
function followingOf(id){const set=id==='me'?S.follows:(S.graph[id]||new Set());return [...set].filter(x=>(x==='me'||PEOPLE[x])&&!isBlocked(x));}
function followersOf(id){return ['me',...Object.keys(PEOPLE)].filter(k=>k!==id&&!isBlocked(k)&&followingOf(k).includes(id));}
function followCounts(id){const a=followersOf(id).length,b=followingOf(id).length;
 return `<div class="fcounts"><button data-go="P10" data-p='${JSON.stringify({id,tab:'followers'})}'><b>${a}</b>${pl(a,['подписчик','подписчика','подписчиков'],['follower','followers'],true)}</button><button data-go="P10" data-p='${JSON.stringify({id,tab:'following'})}'><b>${b}</b>${pl(b,['подписка','подписки','подписок'],['following','following'],true)}</button></div>`;}
SC.P10={title:p=>p.tab==='following'?L('Подписки','Following'):L('Подписчики','Followers'),valid:p=>(p.id==='me'||!!PEOPLE[p.id])&&!isBlocked(p.id),render:(p)=>{const id=p.id,tab=p.tab==='following'?'following':'followers',mine=id==='me';
 const list=tab==='following'?followingOf(id):followersOf(id);
 const row=k=>{const self=k==='me';const fol=S.follows.has(k);
  const act=self?`<span class="note">${L('это ты','you')}</span>`
   :mine&&tab==='followers'?`<button class="btn sm ${fol?'soft':'primary'}" data-act="flwToggle" data-v="${k}" aria-pressed="${fol}">${fol?L('Отписаться','Unfollow'):L('Подписаться в ответ','Follow back')}</button><button class="ibtn sm" data-act="block" data-v="${k}" aria-label="${L(`Заблокировать ${pname(k)}`,`Block ${pname(k)}`)}">${I.block}</button>`
   :`<button class="btn sm ${fol?'soft':'primary'}" data-act="flwToggle" data-v="${k}" aria-pressed="${fol}">${fol?L('Отписаться','Unfollow'):L('Подписаться','Follow')}</button>`;
  return `<div class="li frow"><button class="frow-go" data-go="${self?'P03':'P01'}" ${self?'':`data-p='${JSON.stringify({id:k})}'`}>${av(k,'')}<span class="tx"><b>${esc(pname(k))}${nameBadges(person(k),1)}</b><small>${esc(placeLine(k)||'')}</small></span></button>${act}</div>`;};
 const who=mine?'':` · ${esc(pname(id))}`;
 return `${bar((tab==='following'?L('Подписки','Following'):L('Подписчики','Followers'))+who,{back:1,sm:1})}<div class="view nodock"><div class="wrap">
 ${seg([['followers',`${L('Подписчики','Followers')} · ${followersOf(id).length}`],['following',`${L('Подписки','Following')} · ${followingOf(id).length}`]],tab,'flwTab')}
 ${mine&&tab==='followers'?`<p class="note" style="margin:12px 2px">${L('Подписка показывает публикации в ленте «Подписки». Она не открывает чат и приватные разделы. Заблокированный человек исчезнет из списка.','Following shows posts in the Following feed. It doesn’t open chat or private sections. A blocked person disappears from the list.')}</p>`:''}
 ${list.length?`<div class="card list mt12">${list.map(row).join('')}</div>`:empty('people',tab==='following'?L('Пока ни на кого не подписан(а)','Not following anyone yet'):L('Подписчиков пока нет','No followers yet'),'')}</div></div>`;}};
ACT.flwTab=a=>{const r=cur();r.p={...r.p,tab:a.dataset.v};refresh();};
ACT.flwToggle=a=>{const id=a.dataset.v;if(!PEOPLE[id]||isBlocked(id))return;const on=!S.follows.has(id);on?S.follows.add(id):S.follows.delete(id);refresh();toast(on?L(`Подписка на ${pname(id)}`,`Following ${pname(id)}`):L(`Ты отписался(ась) от ${pname(id)}`,`Unfollowed ${pname(id)}`),{type:on?'ok':'',action:{label:L('Отменить','Undo'),fn:()=>{if(isBlocked(id))return;on?S.follows.delete(id):S.follows.add(id);refresh();}}});};

/** couple links on a profile: a couple profile names its two accounts, each partner links to the couple */
function pairLine(id,o={}){const p=person(id);if(!p)return '';
 if(p.pair&&p.members)return grp(L('Общий профиль двух аккаунтов','A couple profile of two accounts'),p.members.map(m=>personRow(m,{sub:L('личный профиль','personal profile')})).join(''),{list:1,foot:L('Чаты, симпатии и доступы у каждого свои. Общие доступы открываются только с согласия обоих.','Chats, likes and grants are personal. Joint grants open only when both agree.')});
 const couple=p.pairOf&&PEOPLE[p.pairOf]?['P01',{id:p.pairOf},pname(p.pairOf)]:S.pair?.status==='active'&&(id==='me'||id===S.pair.with)?['Q03',null,pairName()]:null;
 if(!couple)return '';const btn=`<button class="pairline" data-go="${couple[0]}" ${couple[1]?`data-p='${JSON.stringify(couple[1])}'`:''}>${I.couple}<span>${L('В паре','In a couple')} · <b>${esc(couple[2])}</b></span>${I.chev}</button>`;
 return o.asOther?btn.replace(/ data-(go|p)=("[^"]*"|'[^']*')/g,'').replace('<button ','<button disabled '):btn;}
